before:
connectSession: this.trpcService.protectedProcedure
      .input(
        z
          .object({
            a1: z.string().min(1).max(8192),
            webSession: z.string().min(1).max(8192),
            persist: z.boolean().optional(),
            replaceSaved: z.boolean().optional(),
            autoRestore: z.boolean().optional(),
          })
          .strict(),
      )
      .mutation(async ({ input, ctx }) => {
        this.requireLocalXhsConnection(ctx);
        try {
          return await this.xhsRuntime!.connectSession(input);
        } catch (error) {
          throw new TRPCError({
            code: 'PRECONDITION_FAILED',
            message: xhsPublicCode(error, 'XHS_CONNECTION_FAILED'),
          });
        }
      })

after:
connectSession: this.trpcService.protectedProcedure
      .input(
        z
          .object({
            a1: z.string().min(1).max(8192),
            webSession: z.string().min(1).max(8192),
            persist: z.boolean().optional(),
            replaceSaved: z.boolean().optional(),
            autoRestore: z.boolean().optional(),
          })
          .strict(),
      )
      .mutation(async ({ input, ctx }) => {
        this.requireLocalXhsConnection(ctx);
        try {
          const connected = await this.xhsRuntime!.connectSession(input);
          return input.persist && this.xhsWhole
            ? await this.xhsWhole.verifyKnownAuthenticationAfterConnection()
            : connected;
        } catch (error) {
          throw new TRPCError({
            code: 'PRECONDITION_FAILED',
            message: xhsPublicCode(error, 'XHS_CONNECTION_FAILED'),
          });
        }
      })

